-- 494_nightly_look_candidates.sql — Phase A1 of NIGHTLY_LOOKS_REFACTOR_PLAN.md: the 26 candidate LOOKS for the
-- nightly catalog, staged as INERT rows (the app never lists them: is_public=false; nightly never rolls them:
-- is_dream_eligible=false, is_scene_eligible=false, nightly_skip=true) exactly like the halloween_* pilot rows
-- (mig 478). Reached ONLY by the QA flag `force_look` (nightly-dreams, Phase A2) until Kevin's grid freezes v1.
-- Authoring rules (BOT_SCENE_QUALITY_PLAYBOOK.md "Medium Looks" + amendments, the face-swap hard rule): pure
-- rendering technique, no time-of-day / weather / lighting words, no artist or studio names, positive-only;
-- face_swap_flux_fragment carries the proven swap-safety clause, flux_fragment is the same look without it,
-- directive is the scene-brief style guide. Locked list (Kevin 2026-09-11): 8 derived from today's nightly
-- pool + the 1.1-pro override fragments, 13 new painted / drawn registers, 5 photographic registers.
INSERT INTO public.dream_mediums
  (key, label, description, directive, flux_fragment, face_swap_flux_fragment, sort_order, allowed_models, preferred_model, client_meta,
   is_active, is_public, is_dream_eligible, is_scene_eligible, is_scene_only, is_character_only, is_bot_only, nightly_skip, face_swaps, character_render_mode)
SELECT v.key, v.label, v.description, v.directive, v.flux_fragment, v.face_swap_flux_fragment, v.sort_order, v.allowed_models, v.preferred_model, v.client_meta,
       true, false, false, false, false, false, false, true, true, 'natural'
FROM (VALUES
  ('nightly_classical_oil', 'Classical Oil', 'Classical oil on canvas, glazed and luminous', 'Render the entire scene as classical oil: classical oil painting, smooth refined brushwork, softly blended tones, rich luminous color, warm chiaroscuro modelling, smooth glazed skin, clean clearly-readable features, elegant oil-on-canvas finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'classical oil painting, smooth refined brushwork, softly blended tones, rich luminous color, warm chiaroscuro modelling, smooth glazed skin, clean clearly-readable features, elegant oil-on-canvas finish', 'classical oil painting with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, smooth refined brushwork, softly blended tones, rich luminous color, warm chiaroscuro modelling, smooth glazed skin, clean clearly-readable features, elegant oil-on-canvas finish', 950, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_digital_painting', 'Digital Painting', 'Polished digital painting, concept-art finish', 'Render the entire scene as digital painting: polished digital painting, professional concept art, smooth painterly surfaces with crisp detail, vibrant saturated colors, masterful fine-art digital painting. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'polished digital painting, professional concept art, smooth painterly surfaces with crisp detail, vibrant saturated colors, masterful fine-art digital painting', 'polished digital painting with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, professional concept art, smooth painterly surfaces with crisp detail, vibrant saturated colors, masterful fine-art digital painting', 951, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_painted_fantasy', 'Painted Fantasy', 'Painted fantasy concept art, jewel tones', 'Render the entire scene as painted fantasy: painted fantasy concept art, oil-painted brushwork, dramatic chiaroscuro modelling, deep saturated jewel tones with painted shadow, rich painterly texture, illustrated-cover realism. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'painted fantasy concept art, oil-painted brushwork, dramatic chiaroscuro modelling, deep saturated jewel tones with painted shadow, rich painterly texture, illustrated-cover realism', 'painted fantasy concept art with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, oil-painted brushwork, dramatic chiaroscuro modelling, deep saturated jewel tones with painted shadow, rich painterly texture, illustrated-cover realism', 952, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_watercolor_ink', 'Watercolor & Ink', 'Loose watercolor and ink, luminous washes', 'Render the entire scene as watercolor & ink: loose watercolor and ink painting, transparent pigment washes on textured watercolor paper, soft feathered bleeding edges, visible brushstrokes and fine ink linework, a luminous palette taking its colours from the scene, painterly realism. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'loose watercolor and ink painting, transparent pigment washes on textured watercolor paper, soft feathered bleeding edges, visible brushstrokes and fine ink linework, a luminous palette taking its colours from the scene, painterly realism', 'loose watercolor and ink painting with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, transparent pigment washes on textured watercolor paper, soft feathered bleeding edges, visible brushstrokes and fine ink linework, a luminous palette taking its colours from the scene, painterly realism', 953, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_ink_illustration', 'Ink Illustration', 'Crisp ink illustration, rich color', 'Render the entire scene as ink illustration: crisp ink illustration with bold confident linework, clean intricate line art, rich saturated color, masterwork hand-drawn editorial illustration, illustrated realism, gallery-quality detailed drawing. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'crisp ink illustration with bold confident linework, clean intricate line art, rich saturated color, masterwork hand-drawn editorial illustration, illustrated realism, gallery-quality detailed drawing', 'crisp ink illustration with bold confident linework with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, clean intricate line art, rich saturated color, masterwork hand-drawn editorial illustration, illustrated realism, gallery-quality detailed drawing', 954, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_storybook_gouache', 'Storybook Gouache', 'Gouache and ink picture-book plate', 'Render the entire scene as storybook gouache: rich gouache and ink storybook painting, opaque matte color fields, painterly textured brushwork, whimsical illustrated realism, hand-painted picture-book plate. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'rich gouache and ink storybook painting, opaque matte color fields, painterly textured brushwork, whimsical illustrated realism, hand-painted picture-book plate', 'rich gouache and ink storybook painting with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, opaque matte color fields, painterly textured brushwork, whimsical illustrated realism, hand-painted picture-book plate', 955, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_film_noir', 'Film Noir', 'Black and white film noir photograph', 'Render the entire scene as film noir: dramatic black and white film noir photograph, rich high-contrast monochrome, deep inky blacks and luminous highlights, bold directional chiaroscuro, fine film grain, dramatic tonal depth. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'dramatic black and white film noir photograph, rich high-contrast monochrome, deep inky blacks and luminous highlights, bold directional chiaroscuro, fine film grain, dramatic tonal depth', 'dramatic black and white film noir photograph with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, rich high-contrast monochrome, deep inky blacks and luminous highlights, bold directional chiaroscuro, fine film grain, dramatic tonal depth', 956, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_vintage_film', 'Vintage Film', 'Faded analog 35mm photograph', 'Render the entire scene as vintage film: nostalgic vintage analog film photograph, 35mm look, warm faded color, soft film grain, gentle halation, muted contrast, aged color cast. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'nostalgic vintage analog film photograph, 35mm look, warm faded color, soft film grain, gentle halation, muted contrast, aged color cast', 'nostalgic vintage analog film photograph with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, 35mm look, warm faded color, soft film grain, gentle halation, muted contrast, aged color cast', 957, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
