  ('nightly_magazine_cover', 'Magazine Cover', 'Mid-century painted magazine cover', 'Render the entire scene as magazine cover: mid-century painted magazine cover illustration, warm painted storytelling realism, confident brush-modelled skin, saturated printed-cover color, crisp editorial finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'mid-century painted magazine cover illustration, warm painted storytelling realism, confident brush-modelled skin, saturated printed-cover color, crisp editorial finish', 'mid-century painted magazine cover illustration with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, warm painted storytelling realism, confident brush-modelled skin, saturated printed-cover color, crisp editorial finish', 961, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
  ('nightly_movie_poster', 'Retro Movie Poster', 'Painted retro movie poster', 'Render the entire scene as retro movie poster: painted retro movie poster illustration, airbrushed painted realism, heroic saturated color, layered poster composition, glossy printed-poster finish. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'painted retro movie poster illustration, airbrushed painted realism, heroic saturated color, layered poster composition, glossy printed-poster finish', 'painted retro movie poster illustration with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, airbrushed painted realism, heroic saturated color, layered poster composition, glossy printed-poster finish', 962, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
