  ('nightly_alla_prima', 'Alla Prima Oil', 'Loose wet-into-wet oil sketch', 'Render the entire scene as alla prima oil: alla prima oil sketch, loose confident wet-into-wet brushstrokes, fully modelled skin, thick expressive paint, fresh direct painterly realism. Every surface, figure and material in this one medium, with people rendered as real adults with lifelike faces.', 'alla prima oil sketch, loose confident wet-into-wet brushstrokes, fully modelled skin, thick expressive paint, fresh direct painterly realism', 'alla prima oil sketch with lifelike adult faces, realistic human facial proportions with true-to-life eyes at natural size and spacing, loose confident wet-into-wet brushstrokes, fully modelled skin, thick expressive paint, fresh direct painterly realism', 968, ARRAY['black-forest-labs/flux-1.1-pro','black-forest-labs/flux-2-flex']::text[], 'black-forest-labs/flux-1.1-pro', '{"nightly_look_candidate":true,"smart_dream_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"],"smart_dream_default":"black-forest-labs/flux-1.1-pro","recommended_models":["black-forest-labs/flux-1.1-pro","black-forest-labs/flux-2-flex"]}'::jsonb),
